public sealed record LayoutRegion(decimal Left,decimal Bottom,decimal Right,decimal Top);
public sealed record DocumentLayoutLine(int PageNumber,string Text,LayoutRegion? Region,int? TableIndex=null,int? RowIndex=null,IReadOnlyList<string>? Columns=null);
public sealed record DocumentLayoutPage(int Number,string Text,IReadOnlyList<DocumentLayoutLine> Lines);
public sealed record DocumentLayout(IReadOnlyList<DocumentLayoutPage> Pages,string Method){public string Text=>string.Join('\n',Pages.Select(x=>x.Text));}
public sealed record FieldCandidate(string CanonicalCode,string OriginalLabel,string RawValue,string? NormalizedCandidate,int PageNumber,LayoutRegion? Region,string? Section,int? TableIndex,int? RowIndex,int? ColumnIndex,string? UnitCandidate,string Language,IReadOnlyList<string> Signals,DocumentIntelligenceConfidence ConfidenceLevel,FieldRecognitionMethod RecognitionMethod,bool RequiresReview=false,string? GroupKey=null,int? Sequence=null,DocumentFieldSourceKind SourceKind=DocumentFieldSourceKind.EXTRACTED);
public sealed record DocumentIntelligenceResult(Guid DocumentId,int Version,DocumentIntelligenceStatus Status,string DocumentTypeCode,string? Language,bool OcrUsed,int FieldCount,int LineItemCount,string Explanation);
public sealed record OcrExtractionResult(bool Available,bool Success,string? ErrorCode,IReadOnlyList<DocumentLayoutPage> Pages,IReadOnlyList<int> OcrPages,string Explanation);

public interface IPdfLayoutExtractor { Task<DocumentLayout> ExtractAsync(Stream stream,int maxPages,CancellationToken ct); }
public sealed class PdfPigLayoutExtractor : IPdfLayoutExtractor {
  public Task<DocumentLayout> ExtractAsync(Stream stream,int maxPages,CancellationToken ct){
    try{
      using var memory=new MemoryStream();stream.CopyTo(memory);using var pdf=PdfDocument.Open(memory.ToArray());var pages=new List<DocumentLayoutPage>();
      foreach(var page in pdf.GetPages().Take(maxPages)){ct.ThrowIfCancellationRequested();var lines=new List<DocumentLayoutLine>();var groups=page.Letters.GroupBy(x=>Math.Round(x.BoundingBox.Bottom,1)).OrderByDescending(x=>x.Key).ToList();var row=0;
        foreach(var group in groups){var letters=group.OrderBy(x=>x.BoundingBox.Left).ToList();var text=string.Concat(letters.Select(x=>x.Value)).Trim();if(text.Length==0)continue;var region=new LayoutRegion(Convert.ToDecimal(letters.Min(x=>x.BoundingBox.Left)),Convert.ToDecimal(letters.Min(x=>x.BoundingBox.Bottom)),Convert.ToDecimal(letters.Max(x=>x.BoundingBox.Right)),Convert.ToDecimal(letters.Max(x=>x.BoundingBox.Top)));var columns=SplitColumns(text);lines.Add(new(page.Number,text,region,columns.Count>1?0:null,columns.Count>1?row:null,columns.Count>1?columns:null));row++;}
        var pageText=string.Join('\n',lines.Select(x=>x.Text));pages.Add(new(page.Number,pageText,lines));
      }
      return Task.FromResult(new DocumentLayout(pages,"PDF_NATIVE_LAYOUT"));
    }catch{return Task.FromResult(new DocumentLayout([],"PDF_NATIVE_ERROR"));}
  }
  internal static List<string> SplitColumns(string text)=>Regex.Split(text.Trim(),@"\s{2,}|\s*\|\s*").Where(x=>!string.IsNullOrWhiteSpace(x)).Select(x=>x.Trim()).ToList();
}

public interface IOcrTextExtractor { Task<OcrExtractionResult> ExtractAsync(string inputPath,string mimeType,int maxPages,IReadOnlyList<string> languages,CancellationToken ct); }
public sealed class LocalProcessOcrTextExtractor(IConfiguration configuration,ILogger<LocalProcessOcrTextExtractor> logger) : IOcrTextExtractor {
  public async Task<OcrExtractionResult> ExtractAsync(string inputPath,string mimeType,int maxPages,IReadOnlyList<string> languages,CancellationToken ct){
    if(!configuration.GetValue("DocumentIntelligence:Ocr:Enabled",false))return new(false,false,"OCR_UNAVAILABLE",[],[],"OCR local deshabilitado por configuración.");
    var executable=configuration["DocumentIntelligence:Ocr:ExecutablePath"];if(string.IsNullOrWhiteSpace(executable)||!File.Exists(executable))return new(false,false,"OCR_UNAVAILABLE",[],[],"El adaptador OCR local no está instalado o configurado.");
    try{
      var template=configuration["DocumentIntelligence:Ocr:Arguments"]??"\"{input}\" stdout -l {languages}";var arguments=template.Replace("{input}",inputPath,StringComparison.Ordinal).Replace("{languages}",string.Join('+',languages),StringComparison.Ordinal);var start=new ProcessStartInfo(executable,arguments){RedirectStandardOutput=true,RedirectStandardError=true,UseShellExecute=false,CreateNoWindow=true};using var process=Process.Start(start);if(process is null)return new(true,false,"ERROR_DE_LECTURA",[],[],"No fue posible iniciar el OCR local.");var output=await process.StandardOutput.ReadToEndAsync(ct);var error=await process.StandardError.ReadToEndAsync(ct);await process.WaitForExitAsync(ct);if(process.ExitCode!=0||string.IsNullOrWhiteSpace(output)){logger.LogWarning("Local OCR failed with exit code {ExitCode}: {Error}",process.ExitCode,error.Length>300?error[..300]:error);return new(true,false,"DOCUMENT_UNREADABLE",[],[],"OCR no pudo recuperar texto legible.");}var lines=output.Split(['\r','\n'],StringSplitOptions.RemoveEmptyEntries).Select((x,i)=>new DocumentLayoutLine(1,x.Trim(),null,null,i)).ToList();return new(true,true,null,[new(1,output.Trim(),lines)],[1],"Texto recuperado mediante OCR local.");
    }catch(Exception ex) when(ex is not OperationCanceledException){logger.LogWarning(ex,"Local OCR adapter failed");return new(true,false,"ERROR_DE_LECTURA",[],[],"Error controlado del adaptador OCR local.");}
  }
}

public sealed record SemanticClassification(string Code,DocumentIntelligenceConfidence Confidence,IReadOnlyList<string> Evidence,bool Ambiguous);
public interface IDocumentSemanticClassifier { SemanticClassification Classify(DocumentLayout layout,string currentType,string fileName); }
public sealed class DocumentSemanticClassifier : IDocumentSemanticClassifier {
  public SemanticClassification Classify(DocumentLayout layout,string currentType,string fileName){var text=$"{fileName}\n{layout.Text}";var scores=new Dictionary<string,(int Score,List<string> Evidence)>(StringComparer.OrdinalIgnoreCase);void Add(string code,string pattern,string evidence,int weight){if(!Regex.IsMatch(text,pattern,RegexOptions.IgnoreCase))return;if(!scores.TryGetValue(code,out var item))item=(0,[]);item.Score+=weight;item.Evidence.Add(evidence);scores[code]=item;}
    Add("COMMERCIAL_INVOICE",@"\b(invoice|factura)\b","Etiqueta factura/invoice",3);Add("COMMERCIAL_INVOICE",@"unit\s*price|invoice\s*total|sold\s*to","Estructura comercial de factura",2);Add("PACKING_LIST",@"packing\s*list|lista\s+de\s+empaque","Título Packing List",4);Add("PACKING_LIST",@"\b(ctns|cartons?|pallets?|gross\s*weight|net\s*weight|cbm)\b","Estructura logística de empaque",2);Add("COVE_ACK",@"acuse\s+de\s+valor|cantidad\s+umc|clave\s+umc|\bcove\b","Estructura COVE",4);Add("PEDIMENTO",@"pedimento|fracci[oó]n\s+arancelaria|patente\s+aduanal","Estructura de pedimento",4);Add("TRANSPORT_DOCUMENT",@"bill\s+of\s+lading|air\s*waybill|transport\s+document","Estructura de transporte",4);
    if(!scores.ContainsKey(currentType)&&currentType!="OTHER")scores[currentType]=(1,["Tipo confirmado durante la carga"]);if(scores.Count==0)return new("OTHER",DocumentIntelligenceConfidence.LOW,["Sin señales semánticas suficientes"],true);var ordered=scores.OrderByDescending(x=>x.Value.Score).ToList();var ambiguous=ordered.Count>1&&ordered[0].Value.Score==ordered[1].Value.Score;var confidence=ambiguous?DocumentIntelligenceConfidence.LOW:ordered[0].Value.Score>=5?DocumentIntelligenceConfidence.HIGH:DocumentIntelligenceConfidence.MEDIUM;return new(ordered[0].Key,confidence,ordered[0].Value.Evidence,ambiguous);
  }
}

public interface ISemanticFieldResolver { IReadOnlyList<FieldCandidate> Resolve(DocumentLayout layout,string documentType,IReadOnlyList<FieldAlias> aliases,IReadOnlyList<UnitAlias> unitAliases,IReadOnlyList<ApprovedFieldMapping> approvedMappings,string? layoutFingerprint,bool ocrUsed); }
public sealed class SemanticFieldResolver(IFieldNormalizationService normalizer) : ISemanticFieldResolver {
  public IReadOnlyList<FieldCandidate> Resolve(DocumentLayout layout,string documentType,IReadOnlyList<FieldAlias> aliases,IReadOnlyList<UnitAlias> unitAliases,IReadOnlyList<ApprovedFieldMapping> approvedMappings,string? layoutFingerprint,bool ocrUsed){var result=new List<FieldCandidate>();var active=aliases.Where(x=>x.IsActive&&(x.DocumentTypeCode==null||x.DocumentTypeCode.Equals(documentType,StringComparison.OrdinalIgnoreCase))).OrderByDescending(x=>Normalize(x.Alias).Length).ToList();
    foreach(var line in layout.Pages.SelectMany(x=>x.Lines)){var parsed=Parse(line.Text,active);if(parsed is null)continue;var(label,value)=parsed.Value;var baseLabel=Regex.Replace(label,@"\([^)]*\)","").Trim();var matches=active.Where(x=>Normalize(baseLabel)==Normalize(x.Alias)||Normalize(label).StartsWith(Normalize(x.Alias),StringComparison.Ordinal)).ToList();var mapping=approvedMappings.FirstOrDefault(x=>x.IsActive&&Normalize(x.OriginalLabel)==Normalize(baseLabel)&&x.ProviderProfile.LayoutFingerprint==layoutFingerprint);string? code=null;FieldRecognitionMethod method=ocrUsed?FieldRecognitionMethod.OCR_TEXT_LABEL:line.TableIndex.HasValue?FieldRecognitionMethod.PDF_TABLE_HEADER:FieldRecognitionMethod.PDF_TEXT_LABEL;var signals=new List<string>();string language="EN";var review=false;
      if(mapping is not null){code=mapping.CanonicalFieldCode;method=FieldRecognitionMethod.PROVIDER_HINT;signals.Add("Mapping aprobado y fingerprint coincidente");language=matches.FirstOrDefault()?.Language??"EN";}
      else if(matches.Count>0){var grouped=matches.GroupBy(x=>x.CanonicalFieldCode).OrderByDescending(x=>x.Max(a=>a.Priority)).ToList();code=grouped[0].Key;language=grouped[0].First().Language;signals.Add($"Alias: {grouped[0].First().Alias}");if(grouped.Count>1&&grouped[0].Max(x=>x.Priority)==grouped[1].Max(x=>x.Priority)){review=true;code=null;}}
      code=ResolveContext(code,label,value,ref review,signals);if(code is null)continue;var unit=UnitFrom(label,value,unitAliases);var cleaned=CleanValue(code,value,unit);var dataType=Type(code);var normalized=normalizer.Normalize(EffectiveFieldCode(code),cleaned,dataType,unit).Value;var shape=Shape(value);if(shape!="TEXT")signals.Add($"Forma: {shape}");var confidence=review?DocumentIntelligenceConfidence.LOW:signals.Any(x=>x.StartsWith("Alias"))&&shape!="TEXT"?DocumentIntelligenceConfidence.HIGH:method==FieldRecognitionMethod.PROVIDER_HINT?DocumentIntelligenceConfidence.MEDIUM:DocumentIntelligenceConfidence.MEDIUM;var candidate=new FieldCandidate(code,label,cleaned,normalized,line.PageNumber,line.Region,null,line.TableIndex,line.RowIndex,null,unit,language,signals,confidence,method,review);result.Add(candidate);
      if(code==DocumentFieldCodes.Quantity&&unit is not null)result.Add(candidate with{CanonicalCode=DocumentFieldCodes.Unit,RawValue=unit,NormalizedCandidate=NormalizeUnit(unit,unitAliases),UnitCandidate=null,Signals=[..signals,"Unidad vinculada a la cantidad"]});
    }
    if(!result.Any(x=>x.CanonicalCode==DocumentFieldCodes.ShipmentMethod)&&Regex.IsMatch(layout.Text,@"(?i)\bocean\s+freight\b")){var source=layout.Pages.SelectMany(x=>x.Lines).First(x=>Regex.IsMatch(x.Text,@"(?i)\bocean\s+freight\b"));result.Add(new(DocumentFieldCodes.ShipmentMethod,"Ocean Freight",source.Text,"SEA",source.PageNumber,source.Region,"LOGISTICS",source.TableIndex,source.RowIndex,null,null,"EN",["Contexto logístico explícito: Ocean Freight","Inferencia controlada SEA"],DocumentIntelligenceConfidence.LOW,FieldRecognitionMethod.CONTEXT_RULE,true,SourceKind:DocumentFieldSourceKind.INFERRED));}
    return result.GroupBy(x=>new{x.CanonicalCode,x.RawValue,x.PageNumber,x.TableIndex,x.RowIndex}).Select(x=>x.First()).ToList();
  }
  private static (string Label,string Value)? Parse(string text,List<FieldAlias> aliases){var m=Regex.Match(text,@"^\s*(?<label>[^:=]{1,80}?)\s*[:=]\s*(?<value>.+?)\s*$");if(m.Success)return(m.Groups["label"].Value,m.Groups["value"].Value);var normalized=Normalize(text);foreach(var alias in aliases){var key=Normalize(alias.Alias);if(!normalized.StartsWith(key+" ",StringComparison.Ordinal))continue;var index=text.IndexOf(' ');if(index>0)return(text[..index],text[(index+1)..].Trim());}return null;}
  private static string? ResolveContext(string? code,string label,string value,ref bool review,List<string> signals){var l=Normalize(label);if(l is "AMOUNT" or "IMPORTE"){review=true;signals.Add("Etiqueta Amount ambigua sin alcance");return null;}if(l.Contains("LINE AMOUNT")||l.Contains("EXTENSION")){signals.Add("Contexto de renglón");return DocumentFieldCodes.LineTotal;}if(l.Contains("INVOICE TOTAL")||l.Contains("COMMERCIAL TOTAL")||l=="TOTAL FACTURA"){signals.Add("Contexto de total de factura");return DocumentFieldCodes.CommercialTotal;}if(l=="TO"){review=true;signals.Add("Etiqueta To ambigua sin rol");return null;}if(l=="UNITS"){review=true;signals.Add("Etiqueta Units ambigua");return null;}return code;}
  private static string? UnitFrom(string label,string value,IReadOnlyList<UnitAlias> aliases){var parent=Regex.Match(label,@"\((?<unit>[^)]+)\)");if(parent.Success&&FindUnit(parent.Groups["unit"].Value,aliases) is{} p)return p;var suffix=Regex.Match(value,@"(?i)(?<unit>[A-ZÁÉÍÓÚÑ³]+)\s*$");return suffix.Success?FindUnit(suffix.Groups["unit"].Value,aliases):null;}
  private static string? FindUnit(string value,IReadOnlyList<UnitAlias> aliases){var key=Normalize(value);return aliases.FirstOrDefault(x=>x.IsActive&&Normalize(x.Alias)==key)?.CanonicalUnit;}
  private static string NormalizeUnit(string unit,IReadOnlyList<UnitAlias> aliases)=>FindUnit(unit,aliases)??unit.Trim().ToUpperInvariant();
  private static string CleanValue(string code,string value,string? unit){var clean=value.Trim();if(unit is not null)clean=Regex.Replace(clean,@"\s+[A-ZÁÉÍÓÚÑ³]+\s*$","",RegexOptions.IgnoreCase).Trim();if(code is DocumentFieldCodes.Quantity or DocumentFieldCodes.UnitPrice or DocumentFieldCodes.LineTotal or DocumentFieldCodes.CommercialTotal or DocumentFieldCodes.GrossWeight or DocumentFieldCodes.NetWeight or DocumentFieldCodes.VolumeCbm){var m=Regex.Match(clean,@"[-+]?[0-9][0-9.,]*");if(m.Success)return m.Value;}return clean;}
  private static DocumentFieldDataType Type(string code)=>code switch{DocumentFieldCodes.Quantity=>DocumentFieldDataType.QUANTITY,DocumentFieldCodes.UnitPrice or DocumentFieldCodes.LineTotal or DocumentFieldCodes.CommercialTotal or DocumentFieldCodes.Cartons or DocumentFieldCodes.Pallets or DocumentFieldCodes.PiecesPerCarton or DocumentFieldCodes.Length or DocumentFieldCodes.Width or DocumentFieldCodes.Height or DocumentFieldCodes.VolumeCbm=>DocumentFieldDataType.DECIMAL,DocumentFieldCodes.GrossWeight or DocumentFieldCodes.NetWeight=>DocumentFieldDataType.WEIGHT,DocumentFieldCodes.DocumentDate or DocumentFieldCodes.Date or DocumentFieldCodes.ShipDate or DocumentFieldCodes.PaymentDue=>DocumentFieldDataType.DATE,DocumentFieldCodes.Currency=>DocumentFieldDataType.CURRENCY,DocumentFieldCodes.InvoiceNumber or DocumentFieldCodes.DocumentReference or DocumentFieldCodes.PartNumber or DocumentFieldCodes.Sku or DocumentFieldCodes.PoNumber or DocumentFieldCodes.SoNumber=>DocumentFieldDataType.IDENTIFIER,_=>DocumentFieldDataType.TEXT};
  private static string Shape(string value){var v=value.Trim();if(Regex.IsMatch(v,@"^(?:USD|MXN|EUR|US\$|\$)?\s*[0-9][0-9.,]*\s*(?:USD|MXN|EUR)?$",RegexOptions.IgnoreCase))return"MONEY_OR_DECIMAL";if(DateTime.TryParse(v,CultureInfo.InvariantCulture,DateTimeStyles.None,out _))return"DATE";if(Regex.IsMatch(v,@"^[A-Z]{3}$"))return"CURRENCY_OR_CODE";if(Regex.IsMatch(v,@"^[A-Z0-9][A-Z0-9_\-/]{2,}$",RegexOptions.IgnoreCase))return"IDENTIFIER";return"TEXT";}
  internal static string EffectiveFieldCode(string canonical)=>canonical switch{DocumentFieldCodes.CommercialTotal=>DocumentFieldCodes.TotalAmount,DocumentFieldCodes.SellerName=>DocumentFieldCodes.SupplierName,DocumentFieldCodes.DocumentDate=>DocumentFieldCodes.Date,DocumentFieldCodes.ShipmentReference=>DocumentFieldCodes.TransportReference,_=>canonical};
  internal static string Normalize(string value){var normalized=value.Normalize(NormalizationForm.FormD);var chars=normalized.Where(x=>CharUnicodeInfo.GetUnicodeCategory(x)!=UnicodeCategory.NonSpacingMark).ToArray();return Regex.Replace(new string(chars).ToUpperInvariant(),@"[^A-Z0-9]+"," ").Trim();}
}

public interface ICalculatedFieldService { IReadOnlyList<DocumentField> Apply(Guid documentId,int analysisVersion,List<DocumentField> fields); }
public sealed class CalculatedFieldService : ICalculatedFieldService {
  public IReadOnlyList<DocumentField> Apply(Guid documentId,int analysisVersion,List<DocumentField> fields){var added=new List<DocumentField>();var groups=fields.GroupBy(x=>x.GroupKey??$"SEQ:{x.Sequence?.ToString()??"HEADER"}");foreach(var group in groups){var quantity=Numeric(group,DocumentFieldCodes.Quantity);var total=Numeric(group,DocumentFieldCodes.LineTotal)??Numeric(group,DocumentFieldCodes.TotalAmount);if(quantity.HasValue&&quantity!=0&&total.HasValue){var calculated=decimal.Round(total.Value/quantity.Value,6);var extracted=group.FirstOrDefault(x=>(x.CanonicalFieldCode??x.FieldCode)==DocumentFieldCodes.UnitPrice&&x.SourceKind==DocumentFieldSourceKind.EXTRACTED);if(extracted is not null){if(decimal.TryParse(extracted.NormalizedValue,NumberStyles.Number,CultureInfo.InvariantCulture,out var current)){var consistent=Math.Abs(current-calculated)<=.000001m;extracted.RecognitionReason=$"Precio extraído validado contra LINE_TOTAL / QUANTITY = {calculated.ToString(CultureInfo.InvariantCulture)}.";extracted.RequiresReview=!consistent;}}else added.Add(Calculated(documentId,analysisVersion,group,DocumentFieldCodes.UnitPrice,calculated,"LINE_TOTAL / QUANTITY","Cálculo reproducible dentro del mismo alcance."));}
      var length=NumericField(group,DocumentFieldCodes.Length);var width=NumericField(group,DocumentFieldCodes.Width);var height=NumericField(group,DocumentFieldCodes.Height);var hasVolume=group.Any(x=>(x.CanonicalFieldCode??x.FieldCode)==DocumentFieldCodes.VolumeCbm);if(!hasVolume&&length.Field is not null&&width.Field is not null&&height.Field is not null&&length.Value.HasValue&&width.Value.HasValue&&height.Value.HasValue){var units=new[]{length.Field.Unit,width.Field.Unit,height.Field.Unit}.Where(x=>!string.IsNullOrWhiteSpace(x)).Distinct(StringComparer.OrdinalIgnoreCase).ToList();if(units.Count==1&&VolumeFactor(units[0]!) is{} factor){var volume=decimal.Round(length.Value.Value*width.Value.Value*height.Value.Value*factor,6);added.Add(Calculated(documentId,analysisVersion,group,DocumentFieldCodes.VolumeCbm,volume,$"LENGTH × WIDTH × HEIGHT ({units[0]}³ → M³)","Volumen calculado únicamente con tres dimensiones verificables y una unidad homogénea."));}}
    }return added;}
  private static DocumentField Calculated(Guid documentId,int analysisVersion,IGrouping<string,DocumentField> group,string code,decimal value,string formula,string reason)=>new(){OperationDocumentId=documentId,FieldCode=code,CanonicalFieldCode=code,RawValue=value.ToString("0.######",CultureInfo.InvariantCulture),NormalizedValue=value.ToString("0.######",CultureInfo.InvariantCulture),DataType=DocumentFieldDataType.DECIMAL,Currency=group.Select(x=>x.Currency).FirstOrDefault(x=>x is not null),Unit=code==DocumentFieldCodes.VolumeCbm?"M3":null,GroupKey=group.First().GroupKey,Sequence=group.First().Sequence,SourceKind=DocumentFieldSourceKind.CALCULATED,ConfidenceLevel=DocumentIntelligenceConfidence.HIGH,RecognitionMethod=FieldRecognitionMethod.CONTEXT_RULE,Formula=formula,RecognitionReason=reason,AnalysisVersion=analysisVersion,ExtractionMethod=ExtractionMethod.PDF_TEXT,Confidence=1};
  private static decimal? VolumeFactor(string unit)=>unit.ToUpperInvariant() switch{"M"=>1m,"CM"=>0.000001m,"MM"=>0.000000001m,_=>null};
  private static (DocumentField? Field,decimal? Value) NumericField(IEnumerable<DocumentField> fields,string code){var field=fields.FirstOrDefault(x=>(x.CanonicalFieldCode??x.FieldCode)==code);return(field,decimal.TryParse(field?.NormalizedValue,NumberStyles.Number,CultureInfo.InvariantCulture,out var value)?value:null);}
  private static decimal? Numeric(IEnumerable<DocumentField> fields,string code){var field=fields.FirstOrDefault(x=>(x.CanonicalFieldCode??x.FieldCode)==code);return decimal.TryParse(field?.NormalizedValue,NumberStyles.Number,CultureInfo.InvariantCulture,out var value)?value:null;}
}

public interface ISemanticLineItemExtractor { IReadOnlyList<DocumentLineItem> Extract(Guid documentId,DocumentLayout layout,IReadOnlyList<UnitAlias> unitAliases,int maxItems,bool ocrUsed); }
public sealed class SemanticLineItemExtractor : ISemanticLineItemExtractor {
  public IReadOnlyList<DocumentLineItem> Extract(Guid documentId,DocumentLayout layout,IReadOnlyList<UnitAlias> unitAliases,int maxItems,bool ocrUsed){var result=new List<DocumentLineItem>();foreach(var page in layout.Pages){var lines=page.Lines.ToList();for(var i=0;i<lines.Count&&result.Count<maxItems;i++){var header=lines[i].Columns;if(header is null||header.Count<2)continue;var map=header.Select((x,index)=>(Key:Header(x),Index:index)).Where(x=>x.Key is not null).ToDictionary(x=>x.Key!,x=>x.Index,StringComparer.OrdinalIgnoreCase);if(!map.ContainsKey(DocumentFieldCodes.Quantity)||!map.Keys.Any(x=>x is DocumentFieldCodes.PartNumber or DocumentFieldCodes.Sku or DocumentFieldCodes.Description))continue;for(var r=i+1;r<lines.Count&&result.Count<maxItems;r++){var row=lines[r];if(row.Columns is null||row.Columns.Count<header.Count/2)break;if(row.Columns.Select(Header).Count(x=>x is not null)>=2)break;string? V(string key)=>map.TryGetValue(key,out var c)&&c<row.Columns.Count?row.Columns[c].Trim():null;var quantity=Number(V(DocumentFieldCodes.Quantity));var part=V(DocumentFieldCodes.PartNumber)??V(DocumentFieldCodes.Sku);var description=V(DocumentFieldCodes.Description);if(quantity is null&&string.IsNullOrWhiteSpace(part)&&string.IsNullOrWhiteSpace(description))break;var unit=NormalizeUnit(V(DocumentFieldCodes.Unit),unitAliases);result.Add(new(){OperationDocumentId=documentId,Sequence=result.Count+1,ItemNumber=(result.Count+1).ToString(CultureInfo.InvariantCulture),PartNumber=part,Sku=V(DocumentFieldCodes.Sku),Description=description,Model=V(DocumentFieldCodes.Model),SerialNumber=V(DocumentFieldCodes.SerialNumber),LotNumber=V(DocumentFieldCodes.LotNumber),Quantity=quantity,Unit=unit,UnitValue=Number(V(DocumentFieldCodes.UnitPrice)),TotalValue=Number(V(DocumentFieldCodes.LineTotal)),Currency=V(DocumentFieldCodes.Currency),Cartons=Number(V(DocumentFieldCodes.Cartons)),Pallets=Number(V(DocumentFieldCodes.Pallets)),PiecesPerCarton=Number(V(DocumentFieldCodes.PiecesPerCarton)),NetWeight=Number(V(DocumentFieldCodes.NetWeight)),GrossWeight=Number(V(DocumentFieldCodes.GrossWeight)),VolumeCbm=Number(V(DocumentFieldCodes.VolumeCbm)),PoNumber=V(DocumentFieldCodes.PoNumber),SoNumber=V(DocumentFieldCodes.SoNumber),CountryOfOrigin=V(DocumentFieldCodes.CountryOfOrigin),RawLocator=$"Página {page.Number}, tabla 0, fila {r-i}",PageNumber=page.Number,RegionJson=row.Region is null?null:JsonSerializer.Serialize(row.Region),ExtractionMethod=ExtractionMethod.PDF_TEXT,SourceKind=DocumentFieldSourceKind.EXTRACTED,ConfidenceLevel=DocumentIntelligenceConfidence.HIGH,RecognitionMethod=ocrUsed?FieldRecognitionMethod.OCR_TABLE:FieldRecognitionMethod.PDF_TABLE_HEADER,Confidence=.95});}i++;}}return result;}
  private static string? Header(string value){var key=SemanticFieldResolver.Normalize(value);if(Regex.IsMatch(key,@"^(PART( NUMBER| NO)?|ITEM( CODE| NUMBER| NO)?|ART NO)$"))return DocumentFieldCodes.PartNumber;if(key=="SKU")return DocumentFieldCodes.Sku;if(key.Contains("DESCRIPTION")||key.Contains("DESCRIPCION"))return DocumentFieldCodes.Description;if(key is "QTY" or "QUANTITY" or "CANTIDAD" or "PIECES")return DocumentFieldCodes.Quantity;if(key is "UNIT" or "UOM" or "UNIDAD")return DocumentFieldCodes.Unit;if(key.Contains("UNIT PRICE")||key.Contains("PRECIO UNITARIO"))return DocumentFieldCodes.UnitPrice;if(key is "LINE TOTAL" or "LINE AMOUNT" or "EXTENSION" or "IMPORTE")return DocumentFieldCodes.LineTotal;if(key is "CURRENCY" or "MONEDA")return DocumentFieldCodes.Currency;if(key is "CTNS" or "CARTONS" or "CARTONES")return DocumentFieldCodes.Cartons;if(key is "PLTS" or "PALLETS" or "SKIDS")return DocumentFieldCodes.Pallets;if(key.Contains("PIECES PER CARTON")||key.Contains("PIECES CTN"))return DocumentFieldCodes.PiecesPerCarton;if(key is "N W" or "NET WEIGHT")return DocumentFieldCodes.NetWeight;if(key is "G W" or "GROSS WEIGHT")return DocumentFieldCodes.GrossWeight;if(key is "CBM" or "M3" or "VOLUME")return DocumentFieldCodes.VolumeCbm;if(key is "PO" or "PO NUMBER" or "ORDER NO")return DocumentFieldCodes.PoNumber;if(key is "SO" or "SO NUMBER")return DocumentFieldCodes.SoNumber;if(key=="MODEL")return DocumentFieldCodes.Model;if(key.Contains("SERIAL"))return DocumentFieldCodes.SerialNumber;if(key.Contains("LOT")||key.Contains("BATCH"))return DocumentFieldCodes.LotNumber;if(key.Contains("ORIGIN"))return DocumentFieldCodes.CountryOfOrigin;return null;}
  private static decimal? Number(string? value){if(string.IsNullOrWhiteSpace(value))return null;var match=Regex.Match(value,@"[-+]?[0-9][0-9.,]*");if(!match.Success)return null;var clean=match.Value.Contains(',')&&match.Value.Contains('.')?match.Value.Replace(",",""):match.Value.Replace(',','.');return decimal.TryParse(clean,NumberStyles.Number,CultureInfo.InvariantCulture,out var result)?result:null;}
  private static string? NormalizeUnit(string? value,IReadOnlyList<UnitAlias> aliases){if(string.IsNullOrWhiteSpace(value))return null;var key=SemanticFieldResolver.Normalize(value);return aliases.FirstOrDefault(x=>x.IsActive&&SemanticFieldResolver.Normalize(x.Alias)==key)?.CanonicalUnit??value.Trim().ToUpperInvariant();}
}

public interface IDocumentIntelligencePipeline { Task<DocumentIntelligenceResult> AnalyzeAsync(Guid documentId,Guid userId,CancellationToken ct=default); }
public sealed class DocumentIntelligencePipeline(SaceDbContext db,IFileStorageService storage,IDocumentFieldExtractor legacyExtractor,IPdfLayoutExtractor pdfLayout,IOcrTextExtractor ocr,IDocumentSemanticClassifier classifier,ISemanticFieldResolver resolver,ISemanticLineItemExtractor lineItemExtractor,ICalculatedFieldService calculated,IConfiguration configuration) : IDocumentIntelligencePipeline {
  public async Task<DocumentIntelligenceResult> AnalyzeAsync(Guid documentId,Guid userId,CancellationToken ct=default){var initial=await db.OperationDocuments.AsNoTracking().SingleOrDefaultAsync(x=>x.Id==documentId,ct)??throw new KeyNotFoundException("Documento no localizado.");await Log(userId,"DOCUMENT_INTELLIGENCE_STARTED",documentId,"Inició análisis documental canónico.",ct);
    try{await legacyExtractor.ExtractDocumentAsync(documentId,userId,ct);}catch(Exception ex) when(ex is not OperationCanceledException){await Log(userId,"DOCUMENT_NATIVE_TEXT_EXTRACTED",documentId,$"Extracción heredada controlada: {ex.GetType().Name}.",ct);}db.ChangeTracker.Clear();var doc=await db.OperationDocuments.Include(x=>x.DocumentType).Include(x=>x.Fields).Include(x=>x.LineItems).Include(x=>x.Participants).Include(x=>x.IntelligenceAnalyses).SingleAsync(x=>x.Id==documentId,ct);var maxPages=Math.Max(1,configuration.GetValue("DocumentIntelligence:MaxPages",100));var ocrMaxPages=Math.Max(1,configuration.GetValue("DocumentIntelligence:OcrMaxPages",20));var minText=Math.Max(1,configuration.GetValue("DocumentIntelligence:MinimumNativeTextCharacters",40));DocumentLayout layout=new([],"UNSUPPORTED");byte[] bytes=[];await using(var input=await storage.OpenAsync(doc.FilePath,ct)){if(input is not null){using var memory=new MemoryStream();await input.CopyToAsync(memory,ct);bytes=memory.ToArray();if(doc.Extension.Equals(".pdf",StringComparison.OrdinalIgnoreCase))layout=await pdfLayout.ExtractAsync(new MemoryStream(bytes),maxPages,ct);else if(doc.Extension.Equals(".xml",StringComparison.OrdinalIgnoreCase)){var text=Encoding.UTF8.GetString(bytes);layout=new([new(1,text,text.Split(['\r','\n'],StringSplitOptions.RemoveEmptyEntries).Select((x,i)=>new DocumentLayoutLine(1,x.Trim(),null,null,i)).ToList())],"XML_NATIVE");}}}
    await Log(userId,"DOCUMENT_NATIVE_TEXT_EXTRACTED",documentId,$"{layout.Text.Length} caracteres nativos; {layout.Pages.Count} páginas.",ct);var ocrUsed=false;string? ocrError=null;IReadOnlyList<int> ocrPages=[];if(layout.Text.Length<minText&&doc.Extension.Equals(".pdf",StringComparison.OrdinalIgnoreCase)){var temp=Path.Combine(Path.GetTempPath(),$"sace-ocr-{Guid.NewGuid():N}.pdf");try{await File.WriteAllBytesAsync(temp,bytes,ct);var languages=(configuration.GetSection("DocumentIntelligence:Ocr:Languages").Get<string[]>()??["spa","eng"]);var ocrResult=await ocr.ExtractAsync(temp,doc.MimeType,ocrMaxPages,languages,ct);ocrError=ocrResult.ErrorCode;ocrPages=ocrResult.OcrPages;if(ocrResult.Success){layout=new(ocrResult.Pages,"OCR");ocrUsed=true;}await Log(userId,"DOCUMENT_OCR_EXECUTED",documentId,$"Disponible={ocrResult.Available}; éxito={ocrResult.Success}; código={ocrResult.ErrorCode??"OK"}.",ct);}finally{if(File.Exists(temp))File.Delete(temp);}}
    var classification=classifier.Classify(layout,doc.DocumentType.Code,doc.OriginalFileName);await Log(userId,"DOCUMENT_CLASSIFIED",documentId,$"{classification.Code}; confianza {classification.Confidence}; ambiguo={classification.Ambiguous}.",ct);var language=DetectLanguage(layout.Text);var fingerprint=Fingerprint(classification.Code,layout);var aliases=await db.FieldAliases.AsNoTracking().Include(x=>x.CanonicalFieldDefinition).Where(x=>x.IsActive).ToListAsync(ct);var units=await db.UnitAliases.AsNoTracking().Where(x=>x.IsActive).ToListAsync(ct);var mappings=await db.ApprovedFieldMappings.AsNoTracking().Include(x=>x.ProviderProfile).Where(x=>x.IsActive&&x.DocumentTypeCode==classification.Code).ToListAsync(ct);var candidates=resolver.Resolve(layout,classification.Code,aliases,units,mappings,fingerprint,ocrUsed);var analysisVersion=(doc.IntelligenceAnalyses.Max(x=>(int?)x.Version)??0)+1;var semanticItems=lineItemExtractor.Extract(doc.Id,layout,units,Math.Max(1,configuration.GetValue("DocumentIntelligence:MaxLineItems",500)),ocrUsed);if(semanticItems.Count>0){db.DocumentLineItems.RemoveRange(doc.LineItems);doc.LineItems.Clear();db.DocumentLineItems.AddRange(semanticItems);}
    foreach(var candidate in candidates){var fieldCode=SemanticFieldResolver.EffectiveFieldCode(candidate.CanonicalCode);var existing=doc.Fields.Where(x=>!x.IsManuallyConfirmed&&x.FieldCode==fieldCode&&string.Equals(x.NormalizedValue,candidate.NormalizedCandidate,StringComparison.OrdinalIgnoreCase)).OrderByDescending(x=>x.Confidence).FirstOrDefault();if(existing is null){existing=new(){OperationDocumentId=doc.Id,FieldCode=fieldCode,RawValue=candidate.RawValue,NormalizedValue=candidate.NormalizedCandidate,DataType=FieldType(candidate.CanonicalCode),Unit=candidate.UnitCandidate,ExtractionMethod=ocrUsed?ExtractionMethod.PDF_TEXT:doc.Extension==".xml"?ExtractionMethod.XML:ExtractionMethod.PDF_TEXT};db.DocumentFields.Add(existing);}existing.CanonicalFieldCode=candidate.CanonicalCode;existing.OriginalLabel=candidate.OriginalLabel;existing.OriginalLanguage=candidate.Language;existing.PageNumber=candidate.PageNumber;existing.RegionJson=candidate.Region is null?null:JsonSerializer.Serialize(candidate.Region);existing.Section=candidate.Section;existing.TableIndex=candidate.TableIndex;existing.RowIndex=candidate.RowIndex;existing.ColumnIndex=candidate.ColumnIndex;existing.SourceKind=candidate.SourceKind;existing.ConfidenceLevel=candidate.ConfidenceLevel;existing.RecognitionMethod=candidate.RecognitionMethod;existing.RequiresReview=candidate.RequiresReview||candidate.ConfidenceLevel==DocumentIntelligenceConfidence.LOW;existing.OriginalText=candidate.RawValue;existing.RecognitionReason=string.Join("; ",candidate.Signals);existing.AnalysisVersion=analysisVersion;existing.SourceLocator=$"Página {candidate.PageNumber}"+(candidate.Region is null?"":$" / región {candidate.Region.Left},{candidate.Region.Bottom},{candidate.Region.Right},{candidate.Region.Top}");existing.Confidence=candidate.ConfidenceLevel switch{DocumentIntelligenceConfidence.HIGH=>.95,DocumentIntelligenceConfidence.MEDIUM=>.75,_=>.4};}
    var additions=calculated.Apply(doc.Id,analysisVersion,doc.Fields);db.DocumentFields.AddRange(additions);UpdateParticipants(doc,analysisVersion);var status=classification.Ambiguous?DocumentIntelligenceStatus.MANUAL_REVIEW:layout.Text.Length==0?ocrError switch{"OCR_UNAVAILABLE"=>DocumentIntelligenceStatus.OCR_UNAVAILABLE,"DOCUMENT_UNREADABLE"=>DocumentIntelligenceStatus.DOCUMENT_UNREADABLE,_=>DocumentIntelligenceStatus.ERROR_DE_LECTURA}:doc.Fields.Any(x=>x.AnalysisVersion==analysisVersion&&x.RequiresReview)?DocumentIntelligenceStatus.LOW_CONFIDENCE:DocumentIntelligenceStatus.COMPLETED;doc.DetectedLanguage=language;doc.IntelligenceStatus=status;doc.IntelligenceVersion=analysisVersion;doc.OcrUsed=ocrUsed;doc.LastAnalyzedAt=DateTime.UtcNow;doc.ClassificationConfidenceLevel=classification.Confidence;doc.ClassificationEvidenceJson=JsonSerializer.Serialize(classification.Evidence);doc.LayoutFingerprint=fingerprint;
    var snapshot=JsonSerializer.Serialize(new{document=doc.Id,analysisVersion,classification,language,layoutMethod=layout.Method,ocrUsed,ocrPages,status,fields=doc.Fields.Where(x=>x.AnalysisVersion==analysisVersion||x.IsManuallyConfirmed).Select(x=>new{x.Id,x.FieldCode,x.CanonicalFieldCode,x.OriginalLabel,x.RawValue,x.NormalizedValue,x.Unit,x.Currency,x.PageNumber,x.RegionJson,x.SourceKind,x.RecognitionMethod,x.ConfidenceLevel,x.RequiresReview,x.Formula,x.RecognitionReason}),lineItems=doc.LineItems.Select(x=>new{x.Id,x.Sequence,x.PartNumber,x.Sku,x.Description,x.Quantity,x.Unit,x.Cartons,x.Pallets,x.PiecesPerCarton,x.NetWeight,x.GrossWeight,x.VolumeCbm,x.PageNumber,x.RegionJson})});db.DocumentIntelligenceAnalyses.Add(new(){OperationDocumentId=doc.Id,Version=analysisVersion,DetectedDocumentTypeCode=classification.Code,ClassificationConfidence=classification.Confidence,ClassificationEvidenceJson=JsonSerializer.Serialize(classification.Evidence),DetectedLanguage=language,ReadingMethod=layout.Method,OcrUsed=ocrUsed,OcrPagesJson=JsonSerializer.Serialize(ocrPages),Status=status,NativeTextLength=layout.Text.Length,FieldCount=doc.Fields.Count(x=>x.AnalysisVersion==analysisVersion||x.IsManuallyConfirmed),LineItemCount=doc.LineItems.Count,LayoutFingerprint=fingerprint,SnapshotJson=snapshot,ErrorCode=ocrError,Explanation=status==DocumentIntelligenceStatus.COMPLETED?"Documento homologado al esquema canónico SACE.":"El documento requiere revisión o soporte de lectura adicional.",CreatedBy=await ValidUser(userId,ct)});await BuildRelationships(doc,classification.Code,ct);await db.SaveChangesAsync(ct);await Log(userId,"DOCUMENT_INTELLIGENCE_COMPLETED",documentId,$"Versión {analysisVersion}; estado {status}; {doc.Fields.Count(x=>x.AnalysisVersion==analysisVersion)} campos; {doc.LineItems.Count} partidas.",ct);return new(doc.Id,analysisVersion,status,classification.Code,language,ocrUsed,doc.Fields.Count(x=>x.AnalysisVersion==analysisVersion),doc.LineItems.Count,status==DocumentIntelligenceStatus.COMPLETED?"Análisis completado.":"Análisis completado con revisión requerida.");
  }
  private static DocumentFieldDataType FieldType(string code)=>code switch{DocumentFieldCodes.Quantity=>DocumentFieldDataType.QUANTITY,DocumentFieldCodes.UnitPrice or DocumentFieldCodes.LineTotal or DocumentFieldCodes.CommercialTotal or DocumentFieldCodes.Cartons or DocumentFieldCodes.Pallets or DocumentFieldCodes.PiecesPerCarton or DocumentFieldCodes.VolumeCbm=>DocumentFieldDataType.DECIMAL,DocumentFieldCodes.GrossWeight or DocumentFieldCodes.NetWeight=>DocumentFieldDataType.WEIGHT,DocumentFieldCodes.DocumentDate or DocumentFieldCodes.Date=>DocumentFieldDataType.DATE,DocumentFieldCodes.Currency=>DocumentFieldDataType.CURRENCY,_=>DocumentFieldDataType.TEXT};
  private void UpdateParticipants(OperationDocument doc,int version){var map=new Dictionary<string,DocumentParticipantRole>{{DocumentFieldCodes.SellerName,DocumentParticipantRole.SELLER},{DocumentFieldCodes.SupplierName,DocumentParticipantRole.SUPPLIER},{DocumentFieldCodes.ManufacturerName,DocumentParticipantRole.MANUFACTURER},{DocumentFieldCodes.ShipperName,DocumentParticipantRole.SHIPPER},{DocumentFieldCodes.BuyerName,DocumentParticipantRole.BUYER},{DocumentFieldCodes.ShipToName,DocumentParticipantRole.SHIP_TO},{DocumentFieldCodes.ConsigneeName,DocumentParticipantRole.CONSIGNEE}};db.DocumentParticipants.RemoveRange(doc.Participants.Where(x=>x.AnalysisVersion>0));foreach(var field in doc.Fields.Where(x=>x.AnalysisVersion==version&&map.ContainsKey(x.CanonicalFieldCode??x.FieldCode)&&!string.IsNullOrWhiteSpace(x.NormalizedValue)))db.DocumentParticipants.Add(new(){OperationDocumentId=doc.Id,Role=map[field.CanonicalFieldCode??field.FieldCode],Name=field.NormalizedValue!,SourceKind=field.SourceKind,ConfidenceLevel=field.ConfidenceLevel,SourceLocator=field.SourceLocator,PageNumber=field.PageNumber,RegionJson=field.RegionJson,AnalysisVersion=version});}
  private async Task BuildRelationships(OperationDocument doc,string documentType,CancellationToken ct){var existing=await db.DocumentRelationshipCandidates.Where(x=>x.SourceDocumentId==doc.Id||x.TargetDocumentId==doc.Id).ToListAsync(ct);db.RemoveRange(existing);var keys=doc.Fields.Where(x=>x.CanonicalFieldCode is DocumentFieldCodes.InvoiceNumber or DocumentFieldCodes.DocumentReference or DocumentFieldCodes.PoNumber or DocumentFieldCodes.SoNumber).Select(x=>x.NormalizedValue).Concat(doc.References.Select(x=>x.Value)).Where(x=>!string.IsNullOrWhiteSpace(x)).Select(x=>SemanticFieldResolver.Normalize(x!)).ToHashSet();if(keys.Count==0)return;var others=await db.OperationDocuments.AsNoTracking().Where(x=>x.TradeOperationId==doc.TradeOperationId&&x.Id!=doc.Id).Include(x=>x.DocumentType).Include(x=>x.Fields).Include(x=>x.References).ToListAsync(ct);foreach(var other in others){var otherKeys=other.Fields.Where(x=>x.CanonicalFieldCode is DocumentFieldCodes.InvoiceNumber or DocumentFieldCodes.DocumentReference or DocumentFieldCodes.PoNumber or DocumentFieldCodes.SoNumber).Select(x=>x.NormalizedValue).Concat(other.References.Select(x=>x.Value)).Where(x=>!string.IsNullOrWhiteSpace(x)).Select(x=>SemanticFieldResolver.Normalize(x!)).ToHashSet();var shared=keys.Intersect(otherKeys).ToList();if(shared.Count==0)continue;db.DocumentRelationshipCandidates.Add(new(){SourceDocumentId=doc.Id,TargetDocumentId=other.Id,RelationshipType=$"{documentType}_RELATED_TO_{other.DocumentType.Code}",EvidenceJson=JsonSerializer.Serialize(shared),ConfidenceLevel=DocumentIntelligenceConfidence.HIGH,ReviewStatus=RelationshipReviewStatus.SUGGESTED,Explanation="Referencias explícitas compartidas; requiere reglas de reconciliación específicas para confirmar alcance."});}}
  internal static string DetectLanguage(string text){var es=Regex.Matches(text,@"(?i)\b(factura|cantidad|descripci[oó]n|proveedor|comprador|peso|fecha)\b").Count;var en=Regex.Matches(text,@"(?i)\b(invoice|quantity|description|supplier|buyer|weight|date)\b").Count;return es==0&&en==0?"UNDETERMINED":es>en?"ES":en>es?"EN":"MIXED";}
  internal static string Fingerprint(string documentType,DocumentLayout layout){var signals=layout.Pages.SelectMany(x=>x.Lines).Select(x=>x.Columns is {Count:>1}?string.Join('|',x.Columns):Regex.Match(x.Text,@"^[^:=]{2,60}(?=[:=])").Value).Where(x=>!string.IsNullOrWhiteSpace(x)).Select(SemanticFieldResolver.Normalize).Distinct().Order().Take(100);return Convert.ToHexString(SHA256.HashData(Encoding.UTF8.GetBytes(documentType+"|"+string.Join('|',signals))));}
  private async Task<Guid?> ValidUser(Guid id,CancellationToken ct)=>id!=Guid.Empty&&await db.Users.AnyAsync(x=>x.Id==id,ct)?id:null;
  private async Task Log(Guid user,string action,Guid documentId,string details,CancellationToken ct){db.SystemAuditLogs.Add(new(){UserId=await ValidUser(user,ct),Action=action,EntityType="OperationDocument",EntityId=documentId.ToString(),Details=details});await db.SaveChangesAsync(ct);}
}

public sealed record CorrectDocumentFieldRequest(string CanonicalFieldCode,string? RawValue,string? Unit,string Reason,string? Evidence,bool ApproveMapping=false,string? ProviderKey=null,string? ProviderName=null);
public interface IDocumentFieldCorrectionService { Task<DocumentField> CorrectAsync(Guid fieldId,CorrectDocumentFieldRequest request,Guid userId,CancellationToken ct=default); }
public sealed class DocumentFieldCorrectionService(SaceDbContext db,IFieldNormalizationService normalizer) : IDocumentFieldCorrectionService {
  public async Task<DocumentField> CorrectAsync(Guid fieldId,CorrectDocumentFieldRequest request,Guid userId,CancellationToken ct=default){if(string.IsNullOrWhiteSpace(request.CanonicalFieldCode)||string.IsNullOrWhiteSpace(request.Reason))throw new ArgumentException("Campo canónico y motivo son obligatorios.");var field=await db.DocumentFields.Include(x=>x.OperationDocument).ThenInclude(x=>x.DocumentType).SingleOrDefaultAsync(x=>x.Id==fieldId,ct)??throw new KeyNotFoundException("Campo no localizado.");var definition=await db.CanonicalFieldDefinitions.SingleOrDefaultAsync(x=>x.Code==request.CanonicalFieldCode,ct)??throw new ArgumentException("Campo canónico no reconocido.");var raw=request.RawValue??field.RawValue;var normalized=normalizer.Normalize(SemanticFieldResolver.EffectiveFieldCode(definition.Code),raw,definition.DataType,request.Unit,field.Currency);db.DocumentFieldCorrections.Add(new(){DocumentFieldId=field.Id,OriginalCanonicalFieldCode=field.CanonicalFieldCode??field.FieldCode,OriginalRawValue=field.RawValue,OriginalNormalizedValue=field.NormalizedValue,CorrectedCanonicalFieldCode=definition.Code,CorrectedRawValue=raw,CorrectedNormalizedValue=normalized.Value,CorrectedUnit=normalized.Unit,Reason=request.Reason,Evidence=request.Evidence,CorrectedBy=userId});field.CanonicalFieldCode=definition.Code;field.FieldCode=SemanticFieldResolver.EffectiveFieldCode(definition.Code);field.RawValue=raw;field.NormalizedValue=normalized.Value;field.Unit=normalized.Unit;field.DataType=definition.DataType;field.SourceKind=DocumentFieldSourceKind.MANUAL;field.ConfidenceLevel=DocumentIntelligenceConfidence.HIGH;field.RecognitionMethod=FieldRecognitionMethod.MANUAL;field.IsManuallyConfirmed=true;field.RequiresReview=false;field.RecognitionReason=request.Reason;field.UpdatedAt=DateTime.UtcNow;
    if(request.ApproveMapping&&!string.IsNullOrWhiteSpace(request.ProviderKey)&&!string.IsNullOrWhiteSpace(field.OriginalLabel)){var documentTypeCode=field.OperationDocument.DocumentType.Code;var profile=await db.ProviderDocumentProfiles.Include(x=>x.Mappings).Where(x=>x.ProviderKey==request.ProviderKey&&x.DocumentTypeCode==documentTypeCode&&x.Status==ProviderProfileStatus.ACTIVE).OrderByDescending(x=>x.Version).FirstOrDefaultAsync(ct);if(profile is null){profile=new(){ProviderKey=request.ProviderKey,ProviderName=request.ProviderName??request.ProviderKey,DocumentTypeCode=documentTypeCode,Status=ProviderProfileStatus.ACTIVE,LayoutFingerprint=field.OperationDocument.LayoutFingerprint};db.ProviderDocumentProfiles.Add(profile);}var context=ContextFingerprint(field);if(!profile.Mappings.Any(x=>x.OriginalLabel==field.OriginalLabel&&x.ContextFingerprint==context&&x.CanonicalFieldCode==definition.Code))profile.Mappings.Add(new(){CanonicalFieldCode=definition.Code,OriginalLabel=field.OriginalLabel,ContextFingerprint=context,Section=field.Section,DocumentTypeCode=profile.DocumentTypeCode,ApprovedBy=userId,Evidence=request.Evidence??"Corrección humana aprobada",Notes=request.Reason});db.SystemAuditLogs.Add(new(){UserId=userId,Action="PROVIDER_MAPPING_APPROVED",EntityType="ProviderDocumentProfile",EntityId=profile.Id.ToString(),Details=$"{field.OriginalLabel} → {definition.Code}; fingerprint exacto requerido."});}
    db.SystemAuditLogs.Add(new(){UserId=userId,Action="DOCUMENT_FIELD_CORRECTED",EntityType="DocumentField",EntityId=field.Id.ToString(),Details=$"{field.OriginalLabel??field.FieldCode} → {definition.Code}; motivo registrado."});await db.SaveChangesAsync(ct);return field;}
  private static string ContextFingerprint(DocumentField field)=>Convert.ToHexString(SHA256.HashData(Encoding.UTF8.GetBytes($"{field.OriginalLabel}|{field.Section}|{field.TableIndex}|{field.ColumnIndex}")));
}
